/* ---------- 工具 ---------- */
function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text !== undefined && text !== null) n.textContent = String(text); return n; }
function parts(b) {
  if (b === null || b === undefined || !isFinite(b)) return null;
  var u = ["B", "KB", "MB", "GB", "TB"], i = 0, v = b;
  while (v >= 1024 && i < u.length - 1) { v /= 1024; i++; }
  return { n: v >= 100 ? v.toFixed(1) : v.toFixed(2), u: u[i] };
}
function fmt(b) { var p = parts(b); return p ? p.n + " " + p.u : null; }
function dt(ms, short) {
  if (!ms) return null;
  var o = short ? { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit", hour12: false } : { hour12: false };
  return new Date(ms).toLocaleString("zh-CN", o);
}
function ago(ms) {
  var s = Math.max(0, (Date.now() - ms) / 1000);
  if (s < 90) return "刚刚";
  if (s < 5400) return Math.round(s / 60) + " 分钟前";
  if (s < 129600) return Math.round(s / 3600) + " 小时前";
  return Math.round(s / 86400) + " 天前";
}
