function ring(percent, c) {
  var NS = "http://www.w3.org/2000/svg", R = 42, C = 2 * Math.PI * R;
  var box = el("div", "ringbox");
  box.style.setProperty("--rc", "var(--" + (c || "accent") + ")");
  var svg = document.createElementNS(NS, "svg"); svg.setAttribute("viewBox", "0 0 100 100");
  function circ(cls) {
    var e = document.createElementNS(NS, "circle");
    e.setAttribute("cx", "50"); e.setAttribute("cy", "50"); e.setAttribute("r", String(R));
    e.setAttribute("fill", "none"); e.setAttribute("stroke-width", "9"); e.setAttribute("class", cls); return e;
  }
  var arc = circ("arc"); arc.setAttribute("stroke-linecap", "round");
  arc.setAttribute("stroke-dasharray", String(C));
  var pct = Math.min(100, Math.max(0, percent));
  var target = C * (1 - pct / 100);
  arc.setAttribute("stroke-dashoffset", firstRender ? String(C) : String(target));
  svg.append(circ("trk"), arc); box.append(svg);
  if (firstRender) requestAnimationFrame(function () { requestAnimationFrame(function () { arc.setAttribute("stroke-dashoffset", String(target)); }); });
  var t = el("div", "ringtxt"); t.append(el("b", "", percent.toFixed(percent >= 10 ? 0 : 1) + "%"), el("span", "", "已使用"));
  box.append(t);
  return box;
}

