function nodesBlock(s, st) {
  var wrap = el("div", "nodes");
  var tested = s.nodes.filter(function (n) { return n.testable; });
  var up = tested.filter(function (n) { return n.online === true; });
  var lats = up.map(function (n) { return n.latencyMs; }).filter(isFinite).sort(function (a, b) { return a - b; });
  var head = el("div", "nh"), left = el("div");
  left.append(el("b", "", "节点"));
  var summary = tested.length
    ? "在线 " + up.length + "/" + tested.length + (lats.length ? " · 中位 " + lats[Math.floor(lats.length / 2)] + " ms" : "")
    : "共 " + s.nodes.length + " 个";
  left.append(el("span", "ns", summary + (s.nodesMore ? " · 另有 " + s.nodesMore + " 个未展示" : "")));
  head.append(left);
  var seg = el("div", "seg"), b1 = el("button", "", "默认"), b2 = el("button", "", "按延迟");
  seg.append(b1, b2); head.append(seg); wrap.append(head);
  var list = el("div"); wrap.append(list);
  var more = el("button", "btn ghost sm more"); wrap.append(more);

  function draw() {
    b1.className = st.byLatency ? "" : "on"; b2.className = st.byLatency ? "on" : "";
    var arr = s.nodes.slice();
    if (st.byLatency) arr.sort(function (a, b) {
      var la = a.online === true && isFinite(a.latencyMs) ? a.latencyMs : 1e9, lb = b.online === true && isFinite(b.latencyMs) ? b.latencyMs : 1e9;
      return la - lb;
    });
    var limit = st.expanded ? arr.length : 6;
    list.replaceChildren.apply(list, arr.slice(0, limit).map(function (n) {
      var r = el("div", "node"), mid = el("div");
      mid.append(el("div", "nname", n.name), el("div", "ntags", [n.protocol, n.transport, n.security].filter(Boolean).join(" · ")));
      r.append(el("span", "ndot " + (n.testable ? (n.online ? "up" : "down") : "")), mid, latPill(n));
      return r;
    }));
    more.style.display = arr.length > 6 ? "" : "none";
    more.textContent = st.expanded ? "收起" : "展开全部 " + arr.length + " 个";
  }
  b1.onclick = function () { st.byLatency = false; draw(); };
  b2.onclick = function () { st.byLatency = true; draw(); };
  more.onclick = function () { st.expanded = !st.expanded; draw(); };
  draw();
  return wrap;
}

