/* ---------- 数据 ---------- */
function request(path, options) {
  options = options || {};
  var headers = Object.assign({}, options.headers, { authorization: "Bearer " + token });
  return fetch(path, Object.assign({}, options, { headers: headers })).then(function (res) {
    return res.json().catch(function () { throw new Error("服务暂时无法返回状态"); }).then(function (data) {
      if (res.status === 401) { $("loginErr").textContent = "口令不正确"; if (!$("login").open) $("login").showModal(); throw new Error("请重新输入访问口令"); }
      if (!res.ok) throw new Error(data.error || "请求失败");
      return data;
    });
  });
}

function load() {
  if (!token) { $("login").showModal(); return Promise.resolve(); }
  return request("/api/status").then(function (data) {
    $("msg").textContent = "";
    var nodes = 0, upn = 0;
    data.subs.forEach(function (s) { (s.nodes || []).forEach(function (n) { if (n.testable) { nodes++; if (n.online) upn++; } }); });
    latestSubs = data.subs; renderDashboard();
    $("sum").textContent = data.subs.length + " 个订阅" + (nodes ? " · 节点在线 " + upn + "/" + nodes : "") + " · 页面每分钟刷新";
    firstRender = false;
  }).catch(function (e) { $("msg").textContent = e.message; });
}

/* ---------- 弹窗与交互 ---------- */
function openPush(id) {
  $("pOrigin").textContent = location.origin; $("pId").textContent = id;
  $("pLine").textContent = "@{ Id = '" + id + "'; Url = '在这里粘贴订阅链接' }";
  $("pushDlg").showModal();
}
document.addEventListener("click", function (e) {
  var b = e.target.closest && e.target.closest("[data-copy]");
  if (!b) return;
  var text = $(b.dataset.copy).textContent, old = b.textContent;
  navigator.clipboard.writeText(text).then(function () { b.textContent = "已复制"; }, function () { b.textContent = "复制失败"; });
  setTimeout(function () { b.textContent = old; }, 1200);
});
