function regionFlag(code){return REGION_FLAGS[code]||"🌐";}
function nodeRegion(n){var matches=REGIONS.filter(function(r){return r[4].test(n.name||'');});return matches.length===1?matches[0]:null;}
function allCleanNodes(){return latestSubs.flatMap(cleanNodes);}
function meter(value,total,color){return segmentMeter(total>0?value/total*100:0,color,'占比');}

function metrics(target){
 var online=latestSubs.filter(s=>s.online===true).length,attention=latestSubs.filter(s=>!s.online||['warning','expired','exhausted'].includes(s.state)).length;
 var nodes=allCleanNodes(),tested=nodes.filter(n=>n.testable&&typeof n.online==='boolean'),up=tested.filter(n=>n.online).length;
 var quotas=latestSubs.filter(s=>s.quotaUpdatedAt&&s.quotaUpdatedAt===s.lastCheck&&Number.isFinite(s.remaining)&&Number.isFinite(s.total)&&s.total>0),remain=quotas.reduce((a,s)=>a+s.remaining,0),total=quotas.reduce((a,s)=>a+s.total,0);
 var rows=[['订阅数据可用',online+' / '+latestSubs.length,online,latestSubs.length,'linear-gradient(90deg,var(--blue),var(--purple))','直连响应 / 已接收快照'],['需关注订阅',String(attention),attention,latestSubs.length,'linear-gradient(90deg,var(--traffic-accent),var(--bad-bar))',attention?'有 '+attention+' 个订阅需要检查':'当前无订阅告警'],['TCP 可达节点',up+' / '+tested.length,up,tested.length,'linear-gradient(90deg,var(--purple),var(--pink))','未探测 '+(nodes.length-tested.length)+' · 仅统计展示节点'],['已知剩余流量',quotas.length?fmt(remain):'暂无额度',remain,total,'linear-gradient(90deg,var(--quota-green),var(--quota-lime))',quotas.length?'总量 '+fmt(total)+' · 剩余 '+Math.round(remain/total*100)+'% · '+quotas.length+' 个订阅':'暂无完整且最新的流量数据']];
 $(target).replaceChildren(...rows.map(function(r,i){var c=el('div','metric glass');c.append(el('small','',r[0]),el('strong','',r[1]));if(i===0&&latestSubs.length){var strip=el('div','status-strip');latestSubs.forEach(s=>{var bit=el('i');bit.style.background=s.online?'var(--success-bar)':'var(--bad-bar)';bit.title=s.name+' · '+(s.online?'可访问':'需检查');strip.append(bit);});c.append(strip);}else c.append(meter(r[2],r[3],r[4]));var note=el('span','',r[5]);note.title=r[5];c.append(note);return c;}));
}
function renderInsights(){
 var nodes=allCleanNodes(),counts={},protocols={},unknown=0;nodes.forEach(n=>{var r=nodeRegion(n);if(r)counts[r[0]]=(counts[r[0]]||0)+1;else unknown++;var p=(n.protocol||'未知').toUpperCase();protocols[p]=(protocols[p]||0)+1;});
 if(!$('view-nodes').hidden){$('regionList').replaceChildren(...Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([code,count])=>{var r=REGIONS.find(r=>r[0]===code),b=el('button','region-chip');b.type='button';b.append(flagIcon(code),regionLabel(code),el('span','country-count',count));b.title=regionName(code)+' · '+count+' 个节点';b.onclick=()=>{globeLon=r[2];globeLat=0;drawGlobe();};return b;}));if(unknown)$('regionList').append(countryUnknown(unknown));
 $('protocolList').replaceChildren(...Object.entries(protocols).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{var row=el('div','protocol-row');row.append(el('b','',name),el('span','',count+' 个'),meter(count,nodes.length,'linear-gradient(90deg,var(--blue),var(--purple))'));return row;}));
 if(!nodes.length)$('protocolList').append(el('p','screen-note','暂无节点数据'));
 var hidden=latestSubs.reduce((a,s)=>a+(s.nodes||[]).filter(isNoticeNode).length,0);$('regionNote').textContent='根据名称 / 国旗推断地区，非 IP 定位；多地区名称归为未知。点阵地图为简化示意。已过滤 '+hidden+' 条公告。统计仅含已采集展示的节点，历史结果沿用最近一次记录。';
 globeCounts=counts;drawGlobe();}
 if(!$('view-control').hidden){
 var files=latestSubs.filter(s=>s.source==='file').length,pull=latestSubs.filter(s=>s.mode!=='push').length,push=latestSubs.length-pull-files;
 $('collectionInfo').replaceChildren(el('p','','直连订阅 '+pull+' 个 · 推送订阅 '+push+' 个 · 文件 '+files+' 个'),...latestSubs.map(s=>{var row=el('div','activity-row');row.append(el('b','',s.name),el('span','',s.source==='file'?'文件快照':s.mode==='push'?'本机推送':'Worker 直连'),el('small','',s.lastCheck?dt(s.lastCheck,true):'尚未采集'));return row;}));
 var issues=latestSubs.filter(s=>!s.online||['warning','expired','exhausted'].includes(s.state));$('issueInfo').replaceChildren(...issues.map(s=>{var row=el('div','activity-row');row.append(el('b','',s.name),el('span','',s.error||(STATE[s.state]||STATE.pending).t));return row;}));if(!issues.length)$('issueInfo').append(el('p','','当前无订阅告警'));} 
}
// Coarse continent outlines, longitude/latitude; local rendering without third-party requests.
