function globeSpinTick(time){if(!globeSpinActive){globeSpinFrame=0;return;}if(globeLastFrame&&!globeDragging&&document.visibilityState!=="hidden"){var elapsed=Math.min(80,time-globeLastFrame);globeLon=(globeLon+elapsed*.0016)%360;drawGlobe();}globeLastFrame=time;globeSpinFrame=requestAnimationFrame(globeSpinTick);}
