var landDots=[];
function inLand(lon,lat){return LAND.some(function(poly){var inside=false;for(var i=0,j=poly.length-1;i<poly.length;j=i++){var a=poly[i],b=poly[j];if(((a[1]>lat)!==(b[1]>lat))&&(lon<(b[0]-a[0])*(lat-a[1])/(b[1]-a[1])+a[0]))inside=!inside;}return inside;});}
for(var dotLat=-58;dotLat<83;dotLat+=1.9){var step=1.9/Math.max(.3,Math.cos(dotLat*Math.PI/180));for(var dotLon=-180;dotLon<180;dotLon+=step)if(inLand(dotLon,dotLat))landDots.push([dotLon,dotLat]);}
function drawGlobe(){var canvas=$('regionGlobe');if(!canvas.getContext)return;var c=canvas.getContext('2d');if(!c)return;var cx=260,cy=195,r=152,dark=document.documentElement.dataset.theme==='dark';c.clearRect(0,0,520,390);
 var halo=c.createRadialGradient(cx,cy,r*.85,cx,cy,r+26);halo.addColorStop(0,dark?'rgba(130,150,200,.08)':'rgba(170,177,204,.13)');halo.addColorStop(1,'rgba(170,177,204,0)');c.fillStyle=halo;c.beginPath();c.arc(cx,cy,r+26,0,Math.PI*2);c.fill();
 var sphere=c.createRadialGradient(cx-55,cy-65,15,cx+25,cy+20,r+50);sphere.addColorStop(0,dark?'#28364e':'#ffffff');sphere.addColorStop(.7,dark?'#202c40':'#f4f4f9');sphere.addColorStop(1,dark?'#111c30':'#d8dbe8');c.beginPath();c.arc(cx,cy,r,0,Math.PI*2);c.fillStyle=sphere;c.fill();
 landDots.forEach(function(p){var q=projectPoint(p[0],p[1]);if(q[2]<0)return;c.beginPath();c.arc(cx+r*q[0],cy-r*q[1],.75+q[2]*.35,0,Math.PI*2);c.fillStyle=dark?'rgba(171,185,218,'+(.28+.55*q[2])+')':'rgba(145,151,179,'+(.2+.43*q[2])+')';c.fill();});
 REGIONS.forEach(function(a){if(!globeCounts[a[0]])return;var q=projectPoint(a[2],a[3]);if(q[2]<.04)return;var x=cx+r*q[0],y=cy-r*q[1],size=3+Math.min(3,Math.sqrt(globeCounts[a[0]])*.5);c.beginPath();c.arc(x,y,size+4,0,Math.PI*2);c.fillStyle='rgba(91,128,247,.15)';c.fill();c.beginPath();c.arc(x,y,size,0,Math.PI*2);c.fillStyle='#6685ed';c.fill();c.strokeStyle=dark?'#c5d2ff':'white';c.lineWidth=1.4;c.stroke();});
 c.beginPath();c.arc(cx,cy,r,0,Math.PI*2);c.strokeStyle=dark?'rgba(189,208,255,.22)':'rgba(255,255,255,.9)';c.lineWidth=1.5;c.stroke();}

