 if(collapsed&&tools.contains(document.activeElement))button.focus();
 headerToolsCollapsed=Boolean(collapsed);
 tools.inert=headerToolsCollapsed;
 tools.setAttribute('aria-hidden',String(headerToolsCollapsed));
 tools.parentElement.dataset.collapsed=String(headerToolsCollapsed);
 button.setAttribute('aria-expanded',String(!headerToolsCollapsed));
 button.title=headerToolsCollapsed?'展开主题与布局按钮':'收起主题与布局按钮';
 button.setAttribute('aria-label',button.title);
 if(save)try{localStorage.setItem('monitor-header-tools-collapsed',headerToolsCollapsed?'1':'0');}catch(_){}
